// Inicializar la base de datos de nodos en el contexto global si no existe
let mapaNodos = global.get('pipea_nodos') || {};
let historialNodos = global.get('pipea_historial') || {};

// Extraer el ID del nodo desde el tópico (pipea/registro/ID)
let topicParts = msg.topic.split('/');
let nodoId = topicParts[2];

let payload = msg.payload;

// Si el payload está vacío o tiene estado offline (LWT o desconexión)
if (!payload || payload.estado === "offline") {
    if (mapaNodos[nodoId]) {
        // Pasar a historial de desconectados guardando sus últimas capacidades
        historialNodos[nodoId] = {
            ...mapaNodos[nodoId],
            ultimo_visto: new Date().toLocaleTimeString(),
            conectado: false
        };
        delete mapaNodos[nodoId];
    }
} else {
    // Nodo Online: Registrar o actualizar capacidades
    mapaNodos[nodoId] = {
        ...payload,
        ultimo_visto: new Date().toLocaleTimeString(),
        conectado: true
    };

    // Si existía en el historial, lo removemos de ahí porque volvió a conectarse
    if (historialNodos[nodoId]) {
        delete historialNodos[nodoId];
    }
}

// Guardar los cambios de vuelta en la memoria global de Node-RED
global.set('pipea_nodos', mapaNodos);
global.set('pipea_historial', historialNodos);

// Enviar los datos consolidados hacia la interfaz visual
msg.payload = {
    conectados: Object.values(mapaNodos),
    historial: Object.values(historialNodos)
};

return msg;

// Esta función intercepta los movimientos de sliders/colores de la interfaz antes de aplicar
// msg.payload debe contener: { nodoId: "lucia_01", parametro: "intensidadPARes", valor: 0.75 }

let nodoId = msg.payload.nodoId;
let parametro = msg.payload.parametro;
let valor = msg.payload.valor;

msg.topic = `pipea/live/${nodoId}/${parametro}`;
msg.payload = valor;

return msg;

// Si el usuario hace clic sobre un nodo en la interfaz, capturamos su ID
if (msg.payload && msg.payload.id) {
    flow.set('nodo_seleccionado_id', msg.payload.id);
}

// Recuperamos la información completa de ese nodo desde la memoria global
let mapaNodos = global.get('pipea_nodos') || {};
let idSeleccionado = flow.get('nodo_seleccionado_id');
let nodoActual = mapaNodos[idSeleccionado];

// Enviamos los datos del nodo seleccionado al panel central
if (nodoActual) {
    msg.payload = nodoActual;
    return msg;
}
return null;

// Validar que el mensaje tenga la estructura esperada
if (!msg.payload || typeof msg.payload !== 'object') {
    return null; 
}

let accion = msg.payload.action;
let nombreArchivo = "obra_default";

if (msg.payload.archivo) {
    nombreArchivo = msg.payload.archivo.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
}

// Ruta dinámica compatible para almacenamiento local
msg.filename = `obra_pipea_${nombreArchivo}.json`;

if (accion === 'guardar') {
    // Tomamos la fotografía de los nodos activos en memoria
    let mapaNodos = global.get('pipea_nodos') || {};

    msg.payload = {
        metadatos: {
            nombre_presentacion: msg.payload.archivo || "Sin Nombre",
            ultima_modificacion: new Date().toISOString()
        },
        configuracion_nodos: mapaNodos
    };

    // Salida 1 va al nodo 'Escribir JSON'
    return [msg, null];

} else if (accion === 'cargar') {
    // Salida 2 va al nodo 'Leer JSON'
    return [null, msg];
}

return null;

let dataObra = JSON.parse(msg.payload);

if (dataObra && dataObra.configuracion_nodos) {
    // 1. Restaurar la base de datos de memoria global con el JSON cargado
    global.set('pipea_nodos', dataObra.configuracion_nodos);

    // 2. Iterar sobre cada uno de los nodos restaurados y enviar su configuración definitiva a la red
    let listaNodos = Object.values(dataObra.configuracion_nodos);
    let mensajesMqtt = [];

    listaNodos.forEach(nodo => {
        mensajesMqtt.push({
            topic: `pipea/config/${nodo.id}`,
            payload: {
                personaje_asignado: nodo.personaje_asignado,
                campos_actualizados: nodo.campos_configurables
            }
        });
    });

    // Enviamos el arreglo completo de mensajes MQTT simultáneamente
    return [ { payload: { conectados: listaNodos, historial: Object.values(global.get('pipea_historial') || {}) } }, mensajesMqtt ];
}
return null;
